(async()=>{
 const closeReview=()=>{if(parent!==window)parent.postMessage({type:'close-core-flow'},location.origin);else location.href='index.html';};document.getElementById('close-review').onclick=closeReview;
 try {
 const $=id=>document.getElementById(id),manifest=await fetch('journey-manifest.json').then(r=>{if(!r.ok)throw Error('The outcomes catalogue could not load.');return r.json();}),screens=manifest.screens,frame=$('fixture');let selected=screens.find(s=>s.id==='nice'),flow=null,step=0,ready=false,loadTimer;
 const transitions={loading:'ready',tutorial:'tutorial-objective','tutorial-objective':'tutorial-hazards','tutorial-hazards':'ready',submitting:'accepted',accepted:'active',resolving:'nice',funds:'stake-selector',rejected:'ready',timeout:'checking',checking:'pending',pending:'recovered-result',connection:'checking',restored:'resumed',offline:'checking',resume:'checking',error:'ready','load-error':'loading','wallet-stale':'checking',maintenance:'checking','recovered-result':'ready','autoplay-stopped':'ready'};
 function send(){if(ready)frame.contentWindow.postMessage({type:'core-fixture',id:selected.id,multiplier:$('variant-wrap').hidden?selected.multiplier:Number($('variant').value)},'*');}
 function variants(){const ranges={nice:[5,9.99],big:[10,24.99],mega:[25,49.99],epic:[50,99.99],legendary:[100],small:[1.01,2,4.99],partial:[.5],even:[1],loss:[0]};const values=ranges[selected.id];$('variant-wrap').hidden=!values;if(values)$('variant').replaceChildren(...values.map(n=>new Option(n+'×',String(n))));}
 function show(id,keepFlow=false){if(!keepFlow)flow=null;selected=screens.find(s=>s.id===id)||screens[0];variants();$('fixture-title').textContent=selected.title;$('fixture-status').textContent='Preview only · no credits used';$('flow-progress').textContent=flow?'Run flow: '+flow.title+' · '+(step+1)+' / '+flow.steps.length+' · Use the screen action or Next.':selected.note||'Isolated $1.00 fixture · Replay resets this preview only.';document.body.classList.add('show-fixture');for(const b of document.querySelectorAll('[data-screen]'))b.setAttribute('aria-current',String(b.dataset.screen===selected.id));ready=false;clearTimeout(loadTimer);$('fixture-status').textContent='Loading preview…';if(!window.IGReviewDocument)throw Error('The preview bundle could not load.');frame.srcdoc=window.IGReviewDocument;loadTimer=setTimeout(()=>{if(!ready){$('fixture-status').textContent='Preview could not start';$('flow-progress').textContent='Select Replay to retry, or Close to return to the game.';}},20000);}
 function advance(){if(flow){if(step<flow.steps.length-1){step++;show(flow.steps[step],true);}else{flow=null;$('flow-progress').textContent='Flow complete. Return to index or replay this screen.';}}else show(transitions[selected.id]||screens[(screens.indexOf(selected)+1)%screens.length].id);}
 function catalogue(){const q=$('search').value.toLowerCase();$('catalogue').replaceChildren();for(const group of [...new Set(screens.map(s=>s.group))]){const rows=screens.filter(s=>s.group===group&&(s.title+' '+s.id).toLowerCase().includes(q));if(!rows.length)continue;const h=document.createElement('h3');h.textContent=group;$('catalogue').append(h);for(const s of rows){const b=document.createElement('button');b.textContent=s.title;b.dataset.screen=s.id;b.onclick=()=>show(s.id);$('catalogue').append(b);}}}
 $('flow-list').innerHTML='<h3>Run flow</h3>';for(const f of manifest.flows){const b=document.createElement('button');b.textContent=f.title;b.onclick=()=>{flow=f;step=0;show(f.steps[0],true);};$('flow-list').append(b);}
 $('search').oninput=catalogue;$('variant').onchange=send;$('next').onclick=advance;$('previous').onclick=()=>{if(flow&&step>0){step--;show(flow.steps[step],true);}else show(screens[(screens.indexOf(selected)-1+screens.length)%screens.length].id);};$('replay').onclick=()=>show(selected.id,!!flow);$('reset').onclick=()=>{flow=null;show('ready');};$('index').onclick=()=>document.body.classList.remove('show-fixture');$('close-review').onclick=()=>{if(parent!==window)parent.postMessage({type:'close-core-flow'},location.origin);else location.href='index.html';};$('viewport').onchange=()=>{frame.style.width=$('viewport').value==='responsive'?'100%':$('viewport').value+'px';};
 window.addEventListener('message',e=>{if(e.source!==frame.contentWindow)return;if(e.data?.type==='fixture-ready'){ready=true;clearTimeout(loadTimer);$('fixture-status').textContent='Preview only · no credits used';send();}if(e.data?.type==='fixture-next')advance();if(e.data?.type==='fixture-error'){clearTimeout(loadTimer);$('fixture-status').textContent='Preview unavailable';$('flow-progress').textContent=e.data.message+' Select Replay to retry.';}});
 document.addEventListener('keydown',e=>{if(e.key==='Escape')$('close-review').click();});catalogue();show('nice');document.body.classList.remove('show-fixture');
}catch(error){document.getElementById('fixture-status').textContent='Outcomes could not load';document.getElementById('flow-progress').textContent=error.message+' Use Replay to reload, or Close to return to the game.';document.getElementById('replay').onclick=()=>location.reload();}
})();
